        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "flux");
        b.append(": ");
        b.append(TableJson.wideText(TableVariable.wide(v.flux.hi, v.flux.lo, true), 0, false));
        if (!first) {
            b.append(',');
        }
        first = false;
        TableJson.indent(b, depth);
        TableJson.esc(b, "ping");
